#!/usr/bin/env bash
# lake-to-data.sh prune|store|hot-main|worktrees|cleanup|all — move Lean build products to the
# NVMe ZFS pool, leaving symlinks at the old paths (owner decision 2026-09-04 15:55Z).
set -u
export PATH="$HOME/.local/bin:$HOME/.elan/bin:$PATH"
D=/data/users/drx/mipstarre-cache; C=$HOME/.cache/mipstarre-dev; P=$HOME/MIPStarRE-qpbt
mkdir -p "$D/lake" "$D/packages" "$D/hot-main"
log() { echo "== $(date -u +%FT%TZ) $*"; }
busy() { local w=$1 p c; for p in /proc/[0-9]*; do c=$(readlink "$p/cwd" 2>/dev/null) || continue; case "$c" in "$w"|"$w"/*) return 0;; esac; done; pgrep -f -- "$w" >/dev/null && return 0; return 1; }
move_dir() { # src dst : src becomes a symlink to dst; the old tree is kept as src.old
  local src=$1 dst=$2
  [ -L "$src" ] && { log "already linked: $src"; return 0; }
  [ -d "$src" ] || { log "missing: $src"; return 1; }
  rsync -a --delete "$src/" "$dst/" || { log "rsync failed: $src"; return 1; }
  mv "$src" "$src.old" && ln -s "$dst" "$src" && log "moved $src -> $dst ($(du -sh "$dst" | cut -f1))"
}
do_prune() { cd "$P" || return 1; for w in .worktrees/issue-0015-* .worktrees/issue-0033-* .worktrees/issue-124-* .worktrees/issue-125-* .worktrees/issue-127-* .worktrees/issue-128-*; do
    [ -d "$w" ] || continue; if busy "$P/$w"; then log "busy, not pruned: $w"; continue; fi
    sz=$(du -sh "$w" | cut -f1); git worktree remove --force "$w" && log "pruned $w ($sz)"; done; git worktree prune; }
do_store() { move_dir "$C/packages" "$D/packages"; }
do_hot() { for _ in 1 2 3 4 5 6; do pgrep -f "cache-warmer.sh|merge-v2.sh" >/dev/null || break; log "warmer/merge running; waiting"; sleep 30; done
  rsync -a --delete "$C/hot-main/" "$D/hot-main/" && pgrep -f "cache-warmer.sh|merge-v2.sh" >/dev/null && { log "warmer started during copy; retry later"; return 1; }
  move_dir "$C/hot-main" "$D/hot-main"; }
do_worktrees() { for w in "$P"/.worktrees/*/; do w=${w%/}; br=$(basename "$w"); [ -d "$w/.lake" ] || continue; [ -L "$w/.lake" ] && continue
    if busy "$w"; then log "busy: $br"; continue; fi
    rsync -a --delete "$w/.lake/" "$D/lake/$br/" || { log "rsync failed: $br"; continue; }
    if busy "$w"; then log "became busy during copy: $br (copy kept, not switched)"; continue; fi
    rm -rf "$w/.lake" && ln -s "$D/lake/$br" "$w/.lake" && log "migrated $br ($(du -sh "$D/lake/$br" | cut -f1))"; done; }
do_cleanup() { for o in "$C/packages.old" "$C/hot-main.old" "$P"/.worktrees/*/.lake.old; do [ -e "$o" ] || continue; w=$(dirname "$o"); case "$o" in */.lake.old) busy "$w" && { log "busy, keeping $o"; continue; };; esac; chmod -R u+w "$o" 2>/dev/null; rm -rf "$o" && log "removed $o"; done; }
case "${1:-}" in prune) do_prune;; store) do_store;; hot-main) do_hot;; worktrees) do_worktrees;; cleanup) do_cleanup;;
  all) do_prune; do_store; do_hot; do_worktrees; log "pass complete"; df -h / /data | tail -2;; *) echo "usage: $0 prune|store|hot-main|worktrees|cleanup|all"; exit 2;; esac
